INSERT INTO departments (id, code, name, description) VALUES
(1, 'CNTT_KHMT', 'Khoa Công nghệ Thông tin & Khoa học Máy tính', 'Đào tạo CNTT, Kỹ thuật phần mềm, Trí tuệ nhân tạo và Khoa học máy tính'),
(2, 'KT_OTO', 'Khoa Kỹ thuật & Công nghệ Ô tô', 'Đào tạo Tự động hóa, Vi mạch bán dẫn, Cơ điện tử, Kỹ thuật ô tô, Kỹ thuật vật liệu và Công nghệ sinh học'),
(3, 'KT_QTKD', 'Khoa Kinh tế & Quản trị Kinh doanh', 'Đào tạo Quản trị kinh doanh, Marketing số, Logistics & Quản lý chuỗi cung ứng, Thương mại điện tử'),
(4, 'TCNH_KT', 'Khoa Tài chính - Ngân hàng & Kế toán', 'Đào tạo Tài chính doanh nghiệp, Ngân hàng thương mại, Fintech và Kế toán - Kiểm toán'),
(5, 'KHSK_YDUOC', 'Khoa Khoa học Sức khỏe & Y Dược', 'Đào tạo Bác sĩ Y khoa, Bác sĩ Răng - Hàm - Mặt, Dược học, Điều dưỡng và Xét nghiệm y học'),
(6, 'NGOAINGU', 'Khoa Ngoại ngữ', 'Đào tạo Ngôn ngữ Anh, Ngôn ngữ Trung Quốc, Ngôn ngữ Hàn Quốc và Ngôn ngữ Nhật Bản'),
(7, 'LUAT_XH', 'Khoa Luật & Khoa học Xã hội', 'Đào tạo Luật kinh tế, Luật thương mại và Pháp lý doanh nghiệp'),
(8, 'DULICH_KS', 'Khoa Du lịch & Khách sạn', 'Đào tạo Quản trị khách sạn, Quản trị ẩm thực và Dịch vụ du lịch lữ hành');
INSERT INTO majors (id, department_id, code, name, description) VALUES
(1, 1, 'CNTT', 'Công nghệ thông tin', 'Kỹ thuật phần mềm, an toàn thông tin và quản trị mạng'),
(2, 1, 'KTPM', 'Kỹ thuật phần mềm', 'Kiến trúc hệ thống, phát triển ứng dụng di động và web cloud'),
(3, 1, 'AI', 'Trí tuệ nhân tạo', 'Học máy, học sâu, thị giác máy tính và xử lý ngôn ngữ tự nhiên'),
(4, 1, 'KHMT', 'Khoa học máy tính', 'Giải thuật nâng cao, cấu trúc dữ liệu lớn và mật mã học'),
(5, 2, 'TDH', 'Kỹ thuật điều khiển & Tự động hóa', 'Hệ thống điều khiển tự động, PLC, SCADA và robot công nghiệp'),
(6, 2, 'BAN_DAN', 'Thiết kế vi mạch bán dẫn', 'Thiết kế VLSI, vật lý bán dẫn, vi mạch số và kiểm thử chip'),
(7, 2, 'CDT', 'Kỹ thuật Cơ điện tử', 'Cơ cấu chính xác, vi điều khiển và hệ thống cơ điện tử thông minh'),
(8, 2, 'OTO', 'Kỹ thuật Ô tô', 'Động cơ đốt trong, hệ thống khung gầm và công nghệ xe điện EV'),
(9, 2, 'KTVL', 'Kỹ thuật vật liệu', 'Khoa học vật liệu nano, polymer, hợp kim và màng mỏng'),
(10, 2, 'CNSH', 'Công nghệ sinh học', 'Sinh học phân tử, kỹ thuật di truyền và vi sinh ứng dụng'),
(11, 3, 'QTKD', 'Quản trị kinh doanh', 'Quản trị chiến lược, quản trị vận hành và nhân sự doanh nghiệp'),
(12, 3, 'MKT_SO', 'Marketing số', 'Digital marketing, SEO/SEM, mạng xã hội và truyền thông số'),
(13, 3, 'LOGISTICS', 'Logistics & Chuỗi cung ứng', 'Quản trị kho vận, chuỗi cung ứng toàn cầu và xuất nhập khẩu'),
(14, 3, 'TMDT', 'Thương mại điện tử', 'Sàn giao dịch TMĐT, bán lẻ đa kênh và thanh toán điện tử'),
(15, 4, 'TCNH', 'Tài chính - Ngân hàng', 'Tài chính doanh nghiệp, ngân hàng số và công nghệ tài chính Fintech'),
(16, 4, 'KETOAN', 'Kế toán', 'Kế toán tài chính, kế toán quản trị và kiểm toán doanh nghiệp'),
(17, 5, 'YKHOA', 'Y khoa', 'Bác sĩ đa khoa, giải phẫu, bệnh học nội - ngoại khoa'),
(18, 5, 'RHM', 'Răng - Hàm - Mặt', 'Bác sĩ Răng Hàm Mặt, giải phẫu răng và điều trị nha khoa'),
(19, 5, 'DUOC', 'Dược học', 'Dược sĩ đại học, hóa dược, bào chế và dược lý lâm sàng'),
(20, 5, 'DIEU_DUONG', 'Điều dưỡng', 'Chăm sóc người bệnh, điều dưỡng lâm sàng và cấp cứu'),
(21, 5, 'XET_NGHIEM', 'Kỹ thuật Xét nghiệm y học', 'Xét nghiệm huyết học, hóa sinh y học và vi sinh lâm sàng'),
(22, 6, 'NN_ANH', 'Ngôn ngữ Anh', 'Tiếng Anh thương mại, biên phiên dịch và sư phạm tiếng Anh'),
(23, 6, 'NN_TRUNG', 'Ngôn ngữ Trung Quốc', 'Tiếng Trung thương mại, Hán ngữ ứng dụng và biên phiên dịch'),
(24, 6, 'NN_HAN', 'Ngôn ngữ Hàn Quốc', 'Tiếng Hàn thương mại, phiên dịch hội thảo và văn hóa Hàn Quốc'),
(25, 6, 'NN_NHAT', 'Ngôn ngữ Nhật Bản', 'Tiếng Nhật thương mại JLPT N1/N2 và biên phiên dịch kỹ thuật'),
(26, 7, 'LUAT_KT', 'Luật kinh tế', 'Pháp luật hợp đồng kinh tế, luật doanh nghiệp và đầu tư quốc tế'),
(27, 8, 'QT_KS', 'Quản trị khách sạn', 'Quản trị tiền sảnh lễ tân, buồng phòng và nhà hàng F&B quốc tế'),
(28, 8, 'DULICH', 'Quản trị dịch vụ du lịch & lữ hành', 'Điều hành tour, thiết kế tuyến du lịch và quản trị sự kiện MICE');
