(97, 'DT201', 'Giải phẫu răng & Mô quanh răng', 3, 'Hình thái cung răng, cắn khớp, tủy răng và sinh bệnh học mô nha chu', 5),
(98, 'DT301', 'Bệnh học miệng & Răng Hàm Mặt', 4, 'Bệnh lý sâu răng, viêm tủy, viêm quanh cuống, chấn thương hàm mặt và phục hình răng', 5),
(99, 'PH201', 'Hóa dược 1', 3, 'Cấu trúc hóa học, cơ chế tác dụng và mối quan hệ cấu trúc - hoạt tính thuốc điều trị', 5),
(100, 'PH202', 'Dược lý học', 4, 'Dược động học hấp thu - phân bố - thải trừ và tác dụng dược lực học các nhóm thuốc', 5);
INSERT INTO subjects (id, subject_code, subject_name, credits, description, department_id) VALUES
(101, 'PH301', 'Bào chế & Sinh dược học', 4, 'Công nghệ sản xuất thuốc viên nén, nang mềm, dung dịch tiêm và đánh giá độ hòa tan', 5),
(102, 'PH302', 'Dược lâm sàng & Điều trị học', 3, 'Tương tác thuốc, phản ứng có hại ADR, giám sát nồng độ thuốc và cá thể hóa liều dùng', 5),
(103, 'NU201', 'Điều dưỡng cơ bản 1', 3, 'Quy trình điều dưỡng, dấu hiệu sinh tồn, vô khuẩn và tiêm truyền tĩnh mạch an toàn', 5),
(104, 'NU202', 'Kỹ thuật điều dưỡng chuyên khoa', 4, 'Chăm sóc người bệnh nội, ngoại khoa, hồi sức cấp cứu và phục hồi chức năng', 5),
(105, 'LB201', 'Kỹ thuật xét nghiệm huyết học', 3, 'Kỹ thuật đếm tế bào máu tự động, xét nghiệm đông máu và định nhóm máu ABO/Rh', 5),
(106, 'LB202', 'Kỹ thuật xét nghiệm hóa sinh', 3, 'Định lượng glucose, ure, creatinin, men gan AST/ALT và phân tích nước tiểu', 5),
(107, 'MD490', 'Thực tập lâm sàng & Khóa luận tốt nghiệp Y Dược', 6, 'Thực tập lâm sàng toàn diện tại bệnh viện đa khoa và báo cáo đề tài tốt nghiệp', 5),
(108, 'FL101', 'Nhập môn ngôn ngữ học đối chiếu', 3, 'Bản chất của ngôn ngữ, ngữ âm, hình thái học, cú pháp học và ngữ nghĩa học', 6),
(109, 'FL102', 'Giao tiếp liên văn hóa', 3, 'Giá trị văn hóa, phong cách giao tiếp phi ngôn ngữ và ứng xử đàm phán quốc tế', 6),
(110, 'EA201', 'Ngữ âm - Âm vị học tiếng Anh', 3, 'Hệ thống nguyên âm, phụ âm IPA, trọng âm từ, ngữ điệu và hiện tượng nối âm', 6),
(111, 'EA202', 'Ngữ pháp nâng cao tiếng Anh', 3, 'Cấu trúc mệnh đề phức hợp, giả định cách, đảo ngữ và văn phong học thuật', 6),
(112, 'EA301', 'Kỹ năng biên phiên dịch tiếng Anh', 4, 'Kỹ thuật dịch xuôi/ngược tài liệu chuyên ngành, dịch đuổi và dịch cabin hội thảo', 6),
(113, 'EA302', 'Tiếng Anh thương mại & Đàm phán quốc tế', 3, 'Soạn thảo hợp đồng ngoại thương, thư tín thương mại và kỹ năng đàm phán song phương', 6),
(114, 'ZH101', 'Tiếng Trung sơ cấp 1 (Hán ngữ 1)', 3, 'Phiên âm Pinyin, các nét chữ Hán cơ bản và giao tiếp chào hỏi hằng ngày', 6),
(115, 'ZH102', 'Tiếng Trung sơ cấp 2 (Hán ngữ 2)', 3, 'Mở rộng 500 từ vựng HSK2, cấu trúc câu vị ngữ động từ và thói quen sinh hoạt', 6),
(116, 'ZH201', 'Tiếng Trung trung cấp 1', 3, 'Giao tiếp thương mại, đọc hiểu văn bản tiếng Trung chuẩn HSK3/4', 6),
(117, 'ZH301', 'Tiếng Trung thương mại & Biên dịch', 3, 'Biên dịch hợp đồng xuất nhập khẩu, thư tín thương mại Trung - Việt', 6),
(118, 'KR101', 'Tiếng Hàn sơ cấp 1', 3, 'Bảng chữ cái Hangul, cách ghép âm, chào hỏi cơ bản và số từ tiếng Hàn', 6),
(119, 'KR102', 'Tiếng Hàn sơ cấp 2', 3, 'Cấu trúc kính ngữ, đuôi câu thân mật, từ vựng sinh hoạt chuẩn Topik 1', 6),
(120, 'KR201', 'Tiếng Hàn trung cấp', 3, 'Ngữ pháp phức, giao tiếp công sở, đàm thoại theo chủ đề chuẩn Topik 3', 6),
(121, 'KR301', 'Tiếng Hàn thương mại & Dịch thuật', 3, 'Dịch hợp đồng, thư tín thương mại và văn hóa kinh doanh doanh nghiệp Hàn Quốc', 6),
(122, 'JA101', 'Tiếng Nhật sơ cấp 1', 3, 'Chữ cái Hiragana, Katakana, Kanji cơ bản và chào hỏi chuẩn JLPT N5', 6),
(123, 'JA102', 'Tiếng Nhật sơ cấp 2', 3, 'Mẫu câu thể Te, thể từ điển, trợ từ và đàm thoại đời sống JLPT N4', 6),
(124, 'JA201', 'Tiếng Nhật trung cấp', 3, 'Kính ngữ Keigo, Khiêm nhường ngữ và kỹ năng đọc hiểu bài xã luận JLPT N3', 6),
(125, 'JA301', 'Tiếng Nhật thương mại & Biên dịch', 3, 'Tác phong doanh nghiệp Nhật Bản Hourensou, email công sở và dịch tài liệu kỹ thuật', 6),
(126, 'FL490', 'Khóa luận tốt nghiệp Ngoại ngữ', 6, 'Nghiên cứu ngôn ngữ học ứng dụng hoặc biên dịch tác phẩm chuyên ngành', 6),
(127, 'LW101', 'Lý luận chung về Nhà nước và Pháp luật', 3, 'Nguồn gốc, bản chất chức năng của nhà nước, quy phạm pháp luật và quan hệ pháp luật', 7),
(128, 'LW102', 'Luật Hiến pháp & Hành chính', 3, 'Tổ chức bộ máy nhà nước, quyền con người và thủ tục xử phạt vi phạm hành chính', 7),
(129, 'LW201', 'Luật Dân sự 1', 3, 'Chủ thể quan hệ dân sự, tài sản, quyền sở hữu, thừa kế và giao dịch dân sự vô hiệu', 7),
(130, 'LW202', 'Luật Thương mại & Hợp đồng kinh tế', 4, 'Quy chế pháp lý thương nhân, hợp đồng mua bán hàng hóa, cung ứng dịch vụ và trọng tài', 7),
(131, 'LW203', 'Luật Doanh nghiệp & Đầu tư', 3, 'Thành lập công ty TNHH, cổ phần, quản trị nội bộ doanh nghiệp và thủ tục cấp phép đầu tư', 7),
(132, 'LW301', 'Luật Tài chính - Ngân hàng & Thuế', 3, 'Pháp luật ngân sách nhà nước, thuế GTGT, thuế TNDN và quy định an toàn vốn tín dụng', 7),
(133, 'LW302', 'Pháp luật Sở hữu trí tuệ', 3, 'Bảo hộ quyền tác giả, sáng chế, nhãn hiệu thương mại, bí mật kinh doanh và chống vi phạm', 7),
(134, 'LW303', 'Giải quyết tranh chấp thương mại quốc tế', 3, 'Tố tụng trọng tài thương mại quốc tế ICC/VIAC, công nhận và thi hành phán quyết', 7),
(135, 'LW490', 'Khóa luận tốt nghiệp Luật Kinh tế', 6, 'Nghiên cứu chuyên sâu giải quyết tranh chấp pháp lý thực tiễn trong kinh doanh', 7),
(136, 'TO101', 'Tổng quan ngành du lịch và khách sạn', 3, 'Hệ thống du lịch, tâm lý du khách, cơ cấu kinh doanh lưu trú và xu hướng du lịch xanh', 8),
(137, 'TO102', 'Địa lý & Tài nguyên du lịch Việt Nam', 3, 'Tài nguyên du lịch tự nhiên, di sản văn hóa phi vật thể và các vùng du lịch trọng điểm', 8),
(138, 'TO201', 'Quản trị tiền sảnh lễ tân khách sạn', 3, 'Quy trình Check-in/Check-out, phần mềm quản lý Opera PMS và xử lý phàn nàn du khách', 8),
(139, 'TO202', 'Quản trị buồng phòng khách sạn', 3, 'Tiêu chuẩn vệ sinh buồng phòng 5 sao, quản lý tài sản đồ vải linen và hóa chất chuyên dụng', 8),
(140, 'TO203', 'Quản trị ẩm thực & Nhà hàng F&B', 3, 'Thiết kế thực đơn Menu engineering, quy trình phục vụ bàn Âu/Á, pha chế Bar và an toàn vệ sinh', 8),
(141, 'TO301', 'Quản trị kinh doanh lữ hành & Điều hành tour', 4, 'Xây dựng giá thành tour, điều hành hướng dẫn viên, liên kết đối tác vận chuyển lưu trú', 8),
(142, 'TO302', 'Marketing du lịch & Khách sạn', 3, 'Xúc tiến điểm đến du lịch, quan hệ công chúng PR, bán hàng qua kênh đại lý OTA Booking/Agoda', 8),
(143, 'TO303', 'Quản trị sự kiện & Du lịch MICE', 3, 'Lập kế hoạch tổ chức hội nghị, hội thảo, triển lãm thương mại MICE và tài trợ sự kiện', 8),
(144, 'TO490', 'Khóa luận tốt nghiệp Du lịch - Khách sạn', 6, 'Đề án phát triển sản phẩm du lịch mới hoặc nâng cao chất lượng dịch vụ khách sạn', 8);
